// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 720, H = 250;
draw.viewbox(0, 0, W, H);

var RPX = 82;                 // circle radius in px (world r = 1)
var CY = 112;
var panels = [
  { cx: 125, color: '#e8722a', label: 'No solutions' },
  { cx: 360, color: '#2f9e44', label: 'One solution' },
  { cx: 595, color: '#d63230', label: 'Two solutions' }
];
var S5 = Math.sqrt(5);
var UX = 1 / S5, UY = -2 / S5;   // screen-space unit direction along line (slope +2, up-right)
var NX = 2 / S5, NY = 1 / S5;    // screen-space unit normal (line offset direction)
var d = 1.5;                     // current distance (world units, r = 1)
var caseOrder = ['noSolution', 'tangent', 'secant'];
var caseOffsets = { noSolution: 1.5, tangent: 1, secant: 0.4 };
var caseIdx = 0;
var eqVisible = false;

var panelGroup = draw.group();
var eqGroup = draw.group().hide();

var lineEls = [], dotGroups = [], dashEls = [], capEls = [], labelEls = [];

panels.forEach(function (p, i) {
  panelGroup.circle(2 * RPX).center(p.cx, CY).fill('none').stroke({ color: p.color, width: 2.5 });
  var ln = panelGroup.line(0, 0, 0, 0).stroke({ color: '#2a6f97', width: 2 });
  lineEls.push(ln);
  var dg = panelGroup.group();
  dotGroups.push(dg);
  var dash = panelGroup.line(0, 0, 0, 0).stroke({ color: '#888', width: 1, dasharray: '4,3' });
  dashEls.push(dash);
  var cap = panelGroup.circle(6).fill('#555');
  capEls.push(cap);
  var lbl = panelGroup.text(p.label)
    .font({ family: 'Georgia, serif', size: 17 })
    .center(p.cx, 232);
  labelEls.push(lbl);
});

function arrowHead(g, x, y, ux, uy, color) {
  var s = 9, w = 4.5;
  var px = -uy, py = ux;
  g.polygon([
    [x, y],
    [x - ux * s + px * w, y - uy * s + py * w],
    [x - ux * s - px * w, y - uy * s - py * w]
  ]).fill(color);
}

function geom(dv) {
  // base point on line nearest to panel center (screen coords)
  var results = [];
  panels.forEach(function (p) {
    var bx = p.cx + dv * RPX * NX;
    var by = CY + dv * RPX * NY;
    var pts = [];
    if (dv < 1) {
      var h = Math.sqrt(1 - dv * dv) * RPX;
      pts.push([bx + h * UX, by + h * UY]);
      pts.push([bx - h * UX, by - h * UY]);
    }
    results.push({ p: p, bx: bx, by: by, pts: pts });
  });
  return results;
}

function redraw() {
  var res = geom(d);
  res.forEach(function (r, i) {
    var ext = RPX * 1.85;
    var x1 = r.bx - ext * UX, y1 = r.by - ext * UY;
    var x2 = r.bx + ext * UX, y2 = r.by + ext * UY;
    lineEls[i].plot(x1, y1, x2, y2);
    var lg = lineEls[i].parent();
    // redraw arrowheads: remove old ones in a dedicated group
    if (!lineEls[i]._heads) lineEls[i]._heads = panelGroup.group();
    lineEls[i]._heads.clear();
    arrowHead(lineEls[i]._heads, x2, y2, UX, UY, '#2a6f97');
    arrowHead(lineEls[i]._heads, x1, y1, -UX, -UY, '#2a6f97');

    dotGroups[i].clear();
    r.pts.forEach(function (pt, j) {
      var c = dotGroups[i].circle(9).fill('#111').center(pt[0], pt[1]);
      c.css('cursor', 'pointer');
      c.on('mousemove', function (e) { showTooltip('Intersection point — a solution of the system', e); });
      c.on('mouseleave', function () { hideTooltip(); });
      c.on('click', function () {
        showPopup('Solution point', 'This point lies on both the circle and the line, so its coordinates satisfy both equations at once. Counting such points counts the solutions: ' + r.pts.length + ' here.');
      });
    });
    // perpendicular distance segment from center to line
    dashEls[i].plot(r.p.cx, CY, r.bx, r.by);
    capEls[i].center(r.p.cx, CY);
  });
  var tangent = Math.abs(d - 1) < 0.005;
  labelEls.forEach(function (l) { l.font({ weight: 'normal', size: 17 }); });
  if (tangent) labelEls[1].font({ weight: 'bold' });
  else if (d > 1) labelEls[0].font({ weight: 'bold' });
  else labelEls[2].font({ weight: 'bold' });
  updateEq();
}

/* ── Equation view ── */
var eqTexts = {};
(function buildEq() {
  eqGroup.rect(W - 20, H - 20).move(10, 10).fill('#fff').stroke({ color: '#ccc', width: 1 }).radius(8);
  var F = { family: 'Georgia, serif', size: 17 };
  eqGroup.text('Substituting the line into the circle:').font(F).move(40, 30);
  eqGroup.text('Circle:  x² + y² = 1        (radius r = 1)').font(F).move(60, 60);
  eqGroup.text('Line:    y = 2x + k,   where  k = √5 · d').font(F).move(60, 88);
  eqGroup.text('Substitution:  x² + (2x + k)² = 1   →   5x² + 4kx + (k² − 1) = 0').font(F).move(60, 116);
  eqGroup.text('Discriminant:  Δ = (4k)² − 4·5·(k² − 1) = 20(1 − d²)').font(F).move(60, 144);
  eqTexts.readout = eqGroup.text('').font({ family: 'Georgia, serif', size: 19, weight: 'bold' }).move(60, 178);
  eqTexts.mean = eqGroup.text('').font({ family: 'Georgia, serif', size: 15 }).move(60, 206);
})();

function updateEq() {
  var D = 20 * (1 - d * d);
  var sign, color, meaning;
  if (Math.abs(d - 1) < 0.005) { sign = 'Δ = 0'; color = '#2f9e44'; meaning = 'One repeated root — the line is tangent: exactly ONE solution.'; }
  else if (D < 0) { sign = 'Δ < 0  (' + D.toFixed(1) + ')'; color = '#e8722a'; meaning = 'No real roots — the line misses the circle: NO solutions.'; }
  else { sign = 'Δ > 0  (+' + D.toFixed(1) + ')'; color = '#d63230'; meaning = 'Two real roots — the line cuts the circle: TWO solutions.'; }
  eqTexts.readout.text('With d = ' + d.toFixed(2) + ':   ' + sign).fill(color);
  eqTexts.mean.text(meaning).fill('#333');
}

/* ── Interactions ── */
function update_lineOffset(v) {
  d = v;
  if (Math.abs(d - 1) < 0.005) d = 1;
  redraw();
}

function setCase(name) {
  caseIdx = caseOrder.indexOf(name);
  var v = caseOffsets[name];
  document.getElementById('lineOffsetInput').value = v;
  document.getElementById('lineOffsetVal').value = v.toFixed(2);
  update_lineOffset(v);
}

function trigger_caseStepper() {
  caseIdx = (caseIdx + 1) % caseOrder.length;
  setCase(caseOrder[caseIdx]);
  hidePopup();
  showPopup('Case: ' + ['No solutions', 'One solution (tangent)', 'Two solutions (secant)'][caseIdx],
    'Comparing the distance d from the center to the line with the radius r: d > r gives no intersection, d = r gives a tangent (one solution), d < r gives a secant (two solutions).');
}

function toggle_viewMode(on) {
  eqVisible = on;
  if (on) { panelGroup.hide(); eqGroup.show(); }
  else { eqGroup.hide(); panelGroup.show(); }
}

/* ── Demo steps ── */
var steps = [
  { title: 'No solutions', narration: 'The line sits too far from the center — its distance exceeds the radius — so it never touches the circle and the system has no solutions.', state: { caseStepper: 'noSolution', lineOffset: 1.5, viewMode: 'Geometric' } },
  { title: 'One solution (tangent)', narration: 'Slide the line inward until its distance from the center exactly equals the radius: it grazes the circle at a single point — the tangent case, one solution.', state: { caseStepper: 'tangent', lineOffset: 1, viewMode: 'Geometric' } },
  { title: 'Two solutions (secant)', narration: 'Push the line closer than the radius and it cuts through the circle, crossing the rim twice — the secant case, two solutions.', state: { caseStepper: 'secant', lineOffset: 0.4, viewMode: 'Geometric' } },
  { title: 'Connect to algebra', narration: 'Switch to the equation view: substituting the line into the circle\u2019s equation gives a quadratic whose discriminant is negative, zero, or positive in exactly the three cases you just saw.', state: { caseStepper: 'secant', lineOffset: 0.4, viewMode: 'Equation' } }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length;
  var eq = s.state.viewMode === 'Equation';
  document.getElementById('viewModeInput').checked = eq;
  toggle_viewMode(eq);
  setCase(s.state.caseStepper);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

redraw();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

