// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 760, H = 640;
draw.viewbox(0, 0, W, H);

var S5 = Math.sqrt(5);
var UX = 1 / S5, UY = -2 / S5;   // screen unit vector along the line (steep, up-right)
var NX = 2 / S5, NY = 1 / S5;    // screen unit normal (offset direction)
var LINE_COLOR = '#2a6f97';

/* ── Top row: three FIXED canonical cases (never move) ── */
var R1 = 88, CY1 = 128;
var panels = [
  { cx: 128, color: '#e8722a', label: 'No solutions', d: 1.5, key: 'noSolution' },
  { cx: 380, color: '#2f9e44', label: 'One solution', d: 1.0, key: 'tangent' },
  { cx: 632, color: '#d63230', label: 'Two solutions', d: 0.4, key: 'secant' }
];
var topGroup = draw.group();
var ringEls = [];

function arrowHead(g, x, y, ux, uy) {
  var s = 10, w = 5, px = -uy, py = ux;
  g.polygon([
    [x, y],
    [x - ux * s + px * w, y - uy * s + py * w],
    [x - ux * s - px * w, y - uy * s - py * w]
  ]).fill(LINE_COLOR);
}

function drawArrowLine(g, bx, by, ext) {
  var x1 = bx - ext * UX, y1 = by - ext * UY;
  var x2 = bx + ext * UX, y2 = by + ext * UY;
  g.line(x1, y1, x2, y2).stroke({ color: LINE_COLOR, width: 2 });
  arrowHead(g, x2, y2, UX, UY);
  arrowHead(g, x1, y1, -UX, -UY);
}

function intersectPoints(cx, cy, R, d) {
  var bx = cx + d * R * NX, by = cy + d * R * NY;
  var pts = [];
  if (d < 1 - 1e-9) {
    var h = Math.sqrt(1 - d * d) * R;
    pts.push([bx + h * UX, by + h * UY]);
    pts.push([bx - h * UX, by - h * UY]);
  } else if (d < 1 + 1e-9) {
    pts.push([bx, by]);
  }
  return { base: [bx, by], pts: pts };
}

function bindDot(dot, count) {
  dot.css('cursor', 'pointer');
  dot.on('mousemove', function (e) { showTooltip('Intersection point — a solution of the system', e); });
  dot.on('mouseleave', function () { hideTooltip(); });
  dot.on('click', function () {
    showPopup('Solution point', 'This point lies on both the circle and the line, so its coordinates satisfy both equations at once. This panel has ' + count + ' such point(s).');
  });
}

panels.forEach(function (p, i) {
  var g = topGroup.group();
  var geom = intersectPoints(p.cx, CY1, R1, p.d);
  drawArrowLine(g, geom.base[0], geom.base[1], R1 * 1.45);
  g.circle(2 * R1).center(p.cx, CY1).fill('none').stroke({ color: p.color, width: 2.5 });
  // intersection dots drawn at load (one for tangent, two for secant)
  geom.pts.forEach(function (pt) {
    bindDot(g.circle(9).fill('#111').center(pt[0], pt[1]), geom.pts.length);
  });
  var lbl = g.text(p.label).font({ family: 'Georgia, serif', size: 19 }).center(p.cx, 252);
  // focus ring (hidden by default)
  var ring = g.circle(2 * R1 + 18).center(p.cx, CY1)
    .fill('none').stroke({ color: p.color, width: 3, dasharray: '7,5' }).hide();
  ringEls.push(ring);
  // interactions on circle/line/label
  [g.children()[2], lbl].forEach(function (el) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(p.label + ' — d ' + (p.d > 1 ? '>' : p.d < 1 ? '<' : '=') + ' r', e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function () {
      var cmp = p.d > 1 ? 'the center-to-line distance d exceeds the radius r, so the line misses the circle'
        : p.d < 1 ? 'the center-to-line distance d is less than the radius r, so the line cuts the circle twice'
        : 'the center-to-line distance d exactly equals the radius r, so the line is tangent';
      showPopup(p.label, 'In this case ' + cmp + '. Comparing d with r (equivalently, the sign of the discriminant) decides the number of solutions.');
    });
  });
});

/* ── Bottom: explore panel (slider-driven) ── */
var R2 = 88, ECX = 170, ECY = 460;
var d = 1.5;
var exploreGroup = draw.group();
var eqGroup = draw.group().hide();

exploreGroup.text('Explore: drag the slider').font({ family: 'Georgia, serif', size: 15, style: 'italic' }).fill('#666').center(ECX, 330);
exploreGroup.circle(2 * R2).center(ECX, ECY).fill('none').stroke({ color: '#888', width: 2.5 });
var exLineG = exploreGroup.group();
var exDotsG = exploreGroup.group();
var exDash = exploreGroup.line(0, 0, 0, 0).stroke({ color: '#aaa', width: 1, dasharray: '4,3' });
var exCenterDot = exploreGroup.circle(5).fill('#666').center(ECX, ECY);

var readTitle = exploreGroup.text('').font({ family: 'Georgia, serif', size: 19, weight: 'bold' }).move(310, 380);
var readCmp = exploreGroup.text('').font({ family: 'Georgia, serif', size: 16 }).move(310, 415);
var readHint = exploreGroup.text('d > r → no solutions · d = r → tangent (one) · d < r → secant (two)')
  .font({ family: 'Georgia, serif', size: 13 }).fill('#777').move(310, 445);

/* ── Equation view ── */
var eqReadout, eqMean;
(function buildEq() {
  eqGroup.rect(680, 300).move(40, 320).fill('#fff').stroke({ color: '#ccc', width: 1 }).radius(8);
  var F = { family: 'Georgia, serif', size: 17 };
  eqGroup.text('Substituting the line into the circle:').font(F).move(70, 345);
  eqGroup.text('Circle:  x² + y² = 1        (radius r = 1)').font(F).move(90, 378);
  eqGroup.text('Line:    y = 2x + k,   where  k = √5 · d').font(F).move(90, 406);
  eqGroup.text('Substitution:  x² + (2x + k)² = 1   →   5x² + 4kx + (k² − 1) = 0').font(F).move(90, 434);
  eqGroup.text('Discriminant:  Δ = (4k)² − 4·5·(k² − 1) = 20(1 − d²)').font(F).move(90, 462);
  eqReadout = eqGroup.text('').font({ family: 'Georgia, serif', size: 19, weight: 'bold' }).move(90, 500);
  eqMean = eqGroup.text('').font({ family: 'Georgia, serif', size: 15 }).move(90, 532);
})();

function redrawExplore() {
  var geom = intersectPoints(ECX, ECY, R2, d);
  exLineG.clear();
  drawArrowLine(exLineG, geom.base[0], geom.base[1], R2 * 1.45);
  exDotsG.clear();
  geom.pts.forEach(function (pt) {
    bindDot(exDotsG.circle(9).fill('#111').center(pt[0], pt[1]), geom.pts.length);
  });
  exDash.plot(ECX, ECY, geom.base[0], geom.base[1]);

  var n = geom.pts.length;
  var color = n === 0 ? '#e8722a' : n === 1 ? '#2f9e44' : '#d63230';
  var word = n === 0 ? 'No solutions' : n === 1 ? 'One solution (tangent)' : 'Two solutions (secant)';
  var cmp = n === 0 ? 'd > r — the line misses the circle'
    : n === 1 ? 'd = r — the line grazes the circle'
    : 'd < r — the line cuts the circle';
  readTitle.text(word).fill(color);
  readCmp.text('d = ' + d.toFixed(2) + '   vs   r = 1   →   ' + cmp).fill('#333');

  var D = 20 * (1 - d * d);
  var sign, mean;
  if (n === 1) { sign = 'Δ = 0'; mean = 'One repeated root — the line is tangent: exactly ONE solution.'; }
  else if (D < 0) { sign = 'Δ < 0  (' + D.toFixed(1) + ')'; mean = 'No real roots — the line misses the circle: NO solutions.'; }
  else { sign = 'Δ > 0  (+' + D.toFixed(1) + ')'; mean = 'Two real roots — the line cuts the circle: TWO solutions.'; }
  eqReadout.text('With d = ' + d.toFixed(2) + ':   ' + sign).fill(color);
  eqMean.text(mean).fill('#333');
}

/* ── Interactions ── */
var focusStates = ['all', 'noSolution', 'tangent', 'secant'];
var focusLabels = { all: 'all', noSolution: 'no solutions', tangent: 'one solution', secant: 'two solutions' };
var focusIdx = 0;

function applyFocus(key) {
  focusIdx = focusStates.indexOf(key);
  document.getElementById('caseFocusInput').textContent = 'Highlight a case: ' + focusLabels[key];
  ringEls.forEach(function (r, i) {
    if (key === 'all' || panels[i].key === key) r.hide();
  });
  if (key !== 'all') {
    var i = panels.findIndex(function (p) { return p.key === key; });
    if (i >= 0) ringEls[i].show();
  }
}

function trigger_caseFocus() {
  focusIdx = (focusIdx + 1) % focusStates.length;
  applyFocus(focusStates[focusIdx]);
}

function update_lineOffset(v) {
  d = v;
  if (Math.abs(d - 1) < 0.004) d = 1;
  redrawExplore();
}

function setLineOffset(v) {
  document.getElementById('lineOffsetInput').value = v;
  document.getElementById('lineOffsetVal').value = v.toFixed(2);
  update_lineOffset(v);
}

function toggle_viewMode(on) {
  if (on) { exploreGroup.hide(); eqGroup.show(); }
  else { eqGroup.hide(); exploreGroup.show(); }
}

/* ── Demo steps (6) ── */
var steps = [
  { narration: 'All three possibilities are shown at once: the line misses the circle entirely, grazes it at one point, or cuts through it at two. The dots marking intersections are visible from the start.', state: { caseFocus: 'all', lineOffset: 1.5, viewMode: 'Geometric' } },
  { narration: 'Highlighting the left panel: the line\u2019s distance from the center exceeds the radius, so it never touches the circle — no solutions.', state: { caseFocus: 'noSolution', lineOffset: 1.5, viewMode: 'Geometric' } },
  { narration: 'Highlighting the center panel: the line\u2019s distance exactly equals the radius, so it is tangent — one solution, marked by the single dot.', state: { caseFocus: 'tangent', lineOffset: 1, viewMode: 'Geometric' } },
  { narration: 'Highlighting the right panel: the line\u2019s distance is less than the radius, so it crosses the rim twice — two solutions, marked by both dots.', state: { caseFocus: 'secant', lineOffset: 0.4, viewMode: 'Geometric' } },
  { narration: 'Drag the distance slider in the explore panel: the intersection dots vanish, merge into one, and split into two as d passes through r — the three fixed panels are snapshots of this single sweep.', state: { caseFocus: 'all', lineOffset: 0.4, viewMode: 'Geometric' } },
  { narration: 'Switch to the equation view: substituting the line into the circle\u2019s equation gives a quadratic whose discriminant is negative, zero, or positive in exactly the three regimes you just swept through.', state: { caseFocus: 'all', lineOffset: 0.4, viewMode: 'Equation' } }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  document.getElementById('demoNarration').textContent = s.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length;
  var eq = s.state.viewMode === 'Equation';
  document.getElementById('viewModeInput').checked = eq;
  toggle_viewMode(eq);
  applyFocus(s.state.caseFocus);
  setLineOffset(s.state.lineOffset);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

redrawExplore();
applyStep(0);
window.__markRendered();
